drop function if exists public.get_current_user_product_entitlements(); drop function if exists public.get_business_product_access(uuid); create function public.get_current_user_product_entitlements() returns table(service_tier text,location_limit integer,fleet_enabled boolean,enterprise_fleet_enabled boolean) language sql security definer set search_path=public as $$ select e.service_tier,e.location_limit,e.fleet_enabled,e.enterprise_fleet_enabled from public.account_service_entitlements e where e.account_user_id=auth.uid() union all select 'admin'::text,null::integer,true,true from public.profiles p where p.id=auth.uid() and p.role::text in ('admin','platform_admin','super_admin'); $$; create function public.get_business_product_access(p_business_id uuid) returns table(business_id uuid,plan text,location_count integer,location_limit integer,enterprise_enabled boolean,fleet_enabled boolean,is_admin boolean) language sql security definer set search_path=public as $$ with admin as (select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role::text in ('admin','platform_admin','super_admin')) a), member as (select exists(select 1 from public.app_business_memberships m where m.business_id=p_business_id and m.user_id=auth.uid()) a), b as (select x.id,x.business_tier::text tier from public.businesses x where x.id=p_business_id), lc as (select count(*)::integer n from public.locations l where l.business_id=p_business_id and coalesce(l.is_active,true)) select b.id,coalesce(b.tier,'standard'),lc.n,case when coalesce(b.tier,'standard')='growth' then 5 else null end,(coalesce(b.tier,'standard') in ('growth','enterprise')) or admin.a,exists(select 1 from public.account_service_entitlements e where e.account_user_id=auth.uid() and e.fleet_enabled),admin.a from b,lc,admin,member where member.a or admin.a; $$;
